from ta5g_global_var import (
    DEFAULT_ENB_ALIAS,
    DEFAULT_IPHY_ALIAS,
    VM0_ENB_LMP_ETH,
    VM0_IPHY_LMP_ETH,
    DEFAULT_IPHY2_ALIAS,
    VM0_IPHY2_LMP_ETH,
    ENB_SUBDIR
)
from ta5g_interface_tools import ta5g_interface_tools
from .syslog_manager import SyslogManager
from taf.ul.log_collection import log_collection
from taf.collectors.core import core
import os


class syslog_common:
    """
    Interface for syslog common methods.
    """

    def __init__(self, syslog_lib):
        self.syslog_manager = SyslogManager(syslog_lib)
        self.log_collection = log_collection()
        self.collect_core = core()

    def start_default_syslog_for_enb_and_iphy(self, logs_dirpath=None, remote_hosts='127.0.0.1'):
        """
        Starts syslogs for eNB and IPHY for all specified hosts with default aliases.
        :param string logs_dirpath: Path to directory where syslog file should be stored.
        :param tuple or string remote_hosts: Ip addresses of eNB host PCs.
        """
        remote_hosts_list = ta5g_interface_tools.create_remote_host_list(remote_hosts=remote_hosts)
        for remote_host in remote_hosts_list:
            self.start_syslog_for_enb(logs_dirpath=logs_dirpath, remote_hosts=remote_host)
            self.start_syslog_for_iphy(logs_dirpath=logs_dirpath, remote_hosts=remote_host)

    def start_default_syslog_for_enb_and_iphy_aic(self, logs_dirpath=None, remote_host='127.0.0.1', network_elements='gnb_0'):
        """
        Starts syslogs for eNB and IPHY for all specified hosts with default aliases in aic.
        :param string logs_dirpath: Path to directory where syslog file should be stored.
        :param tuple or string remote_hosts: Ip addresses of eNB host PCs.
        """
        self.start_syslog_for_enb_aic(network_elements=network_elements)
        self.start_syslog_for_iphy(logs_dirpath=logs_dirpath, remote_hosts=remote_host)

    def start_syslog_for_enb_aic(self, network_elements='gnb_0'):
        """
        Starts syslog for gNB in aic
        :param list network_elements: by default: gnb_0, network elements to collect logs from. Example: "gnb_0"
                                      or "gnb_0,gnb_1,enb_0", None: all network elements in tl config
        """
        dict_log = {'SyslogLogs': {'type': 'syslog'}, 'SyslogGnbAic': {'type': 'group', 'members': 'SyslogLogs'}}
        self.log_collection.create_collectors_using_testline_information(names='SyslogGnbAic', configuration=dict_log,
                                                                         network_elements=network_elements)
        self.collect_core.set_suite_alias(alias='SyslogGnbAic')
        self.collect_core.setup_collectors(names='SyslogGnbAic')
        self.collect_core.start_collectors(names='SyslogGnbAic')

    def start_default_syslog_for_enb_and_both_iphys(self, logs_dirpath=None, remote_hosts='127.0.0.1'):
        """
        Starts syslogs for eNB and dual IPHYs for all specified hosts with default aliases.
        :param string logs_dirpath: Path to directory where syslog file should be stored.
        :param tuple or string remote_hosts: Ip addresses of eNB host PCs.
        """
        remote_hosts_list = ta5g_interface_tools.create_remote_host_list(remote_hosts=remote_hosts)
        for remote_host in remote_hosts_list:
            self.start_syslog_for_enb(logs_dirpath=logs_dirpath, remote_hosts=remote_host)
            self.start_syslog_for_iphy(logs_dirpath=logs_dirpath, remote_hosts=remote_host)
            self.start_syslog_for_iphy2(logs_dirpath=logs_dirpath, remote_hosts=remote_host)

    def start_syslog_for_enb(
        self,
        logs_dirpath=None,
        log_filename_prefix='default_syslog_enb',
        remote_hosts='127.0.0.1',
        alias=DEFAULT_ENB_ALIAS,
    ):
        """
        Starts syslog for eNB for all specified hosts with default aliases.
        :param string logs_dirpath: Path to directory where syslog file should be stored.
        :param string log_filename_prefix: Prefix for name of file where collected
               data should be stored during collection.
        :param tuple or string remote_hosts: Ip addresses of eNB host PCs.
        :param string alias: Unique identifier for a certain syslog instance.
        """
        remote_hosts_list = ta5g_interface_tools.create_remote_host_list(remote_hosts=remote_hosts)
        for remote_host in remote_hosts_list:
            fixed_alias = ta5g_interface_tools.add_remote_host_suffix(alias=alias, remote_host=remote_host)
            self.syslog_manager.start_syslog_instance(
                log_dir=logs_dirpath,
                log_prefix=log_filename_prefix,
                remote_host=remote_host,
                eth_name=VM0_ENB_LMP_ETH,
                alias=fixed_alias,
            )

    def start_syslog_for_remote_host(
        self,
        logs_dirpath=None,
        log_filename_prefix='default_syslog_remote_host',
        remote_hosts='127.0.0.1',
        alias='default_enb_remote_host',
        virtualenv_dir='test_repo'
    ):
        """
        Starts syslog for eNB for all specified hosts with default aliases.
        :param string logs_dirpath: Path to directory where syslog file should be stored.
        :param string log_filename_prefix: Prefix for name of file where collected
               data should be stored during collection.
        :param tuple or string remote_hosts: Ip addresses of eNB host PCs.
        :param string alias: Unique identifier for a certain syslog instance.
        """
        remote_hosts_list = ta5g_interface_tools.create_remote_host_list(remote_hosts=remote_hosts)
        for remote_host in remote_hosts_list:
            fixed_alias = ta5g_interface_tools.add_remote_host_suffix(alias=alias, remote_host=remote_host)
            self.syslog_manager.start_syslog_instance(
                log_dir=logs_dirpath,
                log_prefix=log_filename_prefix,
                remote_host=remote_host,
                eth_name=VM0_ENB_LMP_ETH,
                alias=fixed_alias,
                virtualenv_dir=virtualenv_dir
            )

    def start_syslog_for_iphy(
        self,
        logs_dirpath=None,
        log_filename_prefix='default_syslog_iphy',
        remote_hosts='127.0.0.1',
        alias=DEFAULT_IPHY_ALIAS,
    ):
        """
        Starts syslog for IPHY for all specified hosts with default aliases.
        :param string logs_dirpath: Path to directory where syslog file should be stored.
        :param string log_filename_prefix: Prefix for name of file where collected data should
               be stored during collection.
        :param tuple or string remote_hosts: Ip addresses of eNB host PCs.
        :param string alias: Unique identifier for a certain syslog instance.
        """
        remote_hosts_list = ta5g_interface_tools.create_remote_host_list(remote_hosts=remote_hosts)
        for remote_host in remote_hosts_list:
            fixed_alias = ta5g_interface_tools.add_remote_host_suffix(alias=alias, remote_host=remote_host)
            self.syslog_manager.start_syslog_instance(
                log_dir=logs_dirpath,
                log_prefix=log_filename_prefix,
                remote_host=remote_host,
                eth_name=VM0_IPHY_LMP_ETH,
                alias=fixed_alias,
            )

    def start_syslog_for_iphy2(
        self,
        logs_dirpath=None,
        log_filename_prefix='default_syslog_iphy2',
        remote_hosts='127.0.0.1',
        alias=DEFAULT_IPHY2_ALIAS,
    ):
        """
        Starts syslog for second IPHY for all specified hosts with default aliases.
        :param string logs_dirpath: Path to directory where syslog file should be stored.
        :param string log_filename_prefix: Prefix for name of file where collected data should be
               stored during collection.
        :param tuple or string remote_hosts: Ip addresses of eNB host PCs.
        :param string alias: Unique identifier for a certain syslog instance.
        """
        remote_hosts_list = ta5g_interface_tools.create_remote_host_list(remote_hosts=remote_hosts)
        for remote_host in remote_hosts_list:
            fixed_alias = ta5g_interface_tools.add_remote_host_suffix(alias=alias, remote_host=remote_host)
            self.syslog_manager.start_syslog_instance(
                log_dir=logs_dirpath,
                log_prefix=log_filename_prefix,
                remote_host=remote_host,
                eth_name=VM0_IPHY2_LMP_ETH,
                alias=fixed_alias,
            )

    def stop_default_syslog_for_enb_and_iphy(self, remote_hosts='127.0.0.1'):
        """
        Stops default eNB and I-PHY syslog and downloads the created files.
        :param tuple or string remote_hosts: Ip addresses of eNB host PCs.
        """
        remote_hosts_list = ta5g_interface_tools.create_remote_host_list(remote_hosts=remote_hosts)
        for remote_host in remote_hosts_list:
            self.stop_syslog_with_specified_alias(alias=DEFAULT_ENB_ALIAS, remote_hosts=remote_host)
            self.stop_syslog_with_specified_alias(alias=DEFAULT_IPHY_ALIAS, remote_hosts=remote_host)

    def stop_default_syslog_for_enb_and_iphy_aic(self, logs_dirpath=None, remote_host='127.0.0.1'):
        """
        Stops default eNB and I-PHY syslog and downloads the created files in aic.
        :param tuple or string remote_hosts: Ip addresses of eNB host PCs.
        """
        self.stop_default_syslog_for_enb_aic(logs_dirpath=logs_dirpath)
        self.stop_syslog_with_specified_alias(alias=DEFAULT_IPHY_ALIAS, remote_hosts=remote_host)

    def stop_default_syslog_for_enb_aic(self, logs_dirpath=None):
        """
        Stop syslog for gNB in aic
        :param string logs_dirpath: Path to directory where syslog file should be stored.
        """
        self.collect_core.stop_collectors(names='SyslogGnbAic')
        self.collect_core.collect_collectors(names='SyslogGnbAic', target_dir=logs_dirpath)
        self.collect_core.teardown_collectors(names='SyslogGnbAic')

    def teardown_all_syslog_aliases(self):
        self.syslog_manager.teardown_all_syslog_aliases()

    def stop_syslog_with_specified_alias(self, alias, remote_hosts='127.0.0.1'):
        """
        Stops syslog with a specified alias and downloads the created file.
        :param string alias: Unique identifier for a certain syslog instance.
        :param tuple or string remote_hosts: Ip addresses of eNB host PCs.
        """
        remote_hosts_list = ta5g_interface_tools.create_remote_host_list(remote_hosts=remote_hosts)
        for remote_host in remote_hosts_list:
            fixed_alias = ta5g_interface_tools.add_remote_host_suffix(alias=alias, remote_host=remote_host)
            self.syslog_manager.syslog_lib.collect_syslog_results(alias=fixed_alias)

    def check_err_or_wrn_in_gnb_syslog(self, output_dirpath=None, err_or_wrn='both'):  # noqa: C901
        if not output_dirpath:
            output_dirpath = ta5g_interface_tools().get_robot_output_dir()
        full_output_path = os.path.join(output_dirpath, ENB_SUBDIR, 'default_syslog_enbNone.log')
        output_path = os.path.join(output_dirpath, ENB_SUBDIR, 'ERRORS_WARNINGS.txt')
        with open(full_output_path, 'r') as infile, open(output_path, 'w') as outfile:
            for line in infile:
                if err_or_wrn.lower() == 'both':
                    if ('WRN/' in line) or ('ERR/' in line):
                        outfile.write(line)
                elif err_or_wrn.lower() == 'err':
                    if 'ERR/' in line:
                        outfile.write(line)
                elif err_or_wrn.lower() == 'wrn':
                    if 'WRN/' in line:
                        outfile.write(line)

    def check_faults_in_gnb_syslog(self, output_dirpath=None):
        if not output_dirpath:
            output_dirpath = ta5g_interface_tools().get_robot_output_dir()
        full_output_path = os.path.join(output_dirpath, ENB_SUBDIR, 'default_syslog_enbNone.log')
        output_path = os.path.join(output_dirpath, ENB_SUBDIR, 'FAULTS.txt')
        with open(full_output_path, 'r') as infile, open(output_path, 'w') as outfile:
            for line in infile:
                if ('[AlarmReporter]' in line) and ('FaultId' in line) and ('AlarmNumber' in line):
                    outfile.write(line)

    def check_if_new_error_appear_in_syslog(self, output_dirpath=None, error_list_file=None, err_or_wrn='both'):  # noqa: C901
        if not output_dirpath:
            output_dirpath = ta5g_interface_tools().get_robot_output_dir()
        full_output_path = os.path.join(output_dirpath, ENB_SUBDIR, 'default_syslog_enbNone.log')
        output_path = os.path.join(output_dirpath, ENB_SUBDIR, 'NEW_ERRORS.txt')
        with open(full_output_path, 'r') as infile, open(error_list_file, 'r') as error_list,  open(output_path, 'w') as outfile:
            for line in infile:
                if err_or_wrn.lower() == 'both':
                    if ('WRN/' in line) or ('ERR/' in line):
                        for error_line in error_list:
                            if error_line in line:
                                break
                        else:
                            outfile.write(line)
                elif err_or_wrn.lower() == 'err':
                    if 'ERR/' in line:
                        for error_line in error_list:
                            if error_line in line:
                                break
                        else:
                            outfile.write(line)
                elif err_or_wrn.lower() == 'wrn':
                    if 'WRN/' in line:
                        for error_line in error_list:
                            if error_line in line:
                                break
                        else:
                            outfile.write(line)
